// Generated by scripts/gen-showcase-s1-code.mjs from the s1 demo sources. Do not edit by hand.
export const s1Code: Record<string, string> = {
  "ButtonActionBar": "\"use client\"\n\nimport { useEffect, useRef, useState } from \"react\"\nimport { Check, FloppyDisk, Trash } from \"@phosphor-icons/react\"\nimport { Badge, Button, Card, CardDescription, CardFooter, CardHeader, CardTitle } from \"@glinui/ui\"\n\nexport function ButtonActionBar() {\n  const [state, setState] = useState<\"idle\" | \"saving\" | \"saved\">(\"idle\")\n  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)\n  useEffect(() => () => clearTimeout(timer.current), [])\n\n  function save() {\n    setState(\"saving\")\n    timer.current = setTimeout(() => setState(\"saved\"), 1400)\n  }\n\n  return (\n    <Card className=\"w-full max-w-xl\">\n      <CardHeader>\n        <div className=\"flex items-center justify-between gap-3\">\n          <CardTitle>Release notes for v2.4</CardTitle>\n          <Badge tone={state === \"saved\" ? \"success\" : \"warning\"} variant=\"soft\" dot>\n            {state === \"saved\" ? \"Saved\" : \"Unsaved changes\"}\n          </Badge>\n        </div>\n        <CardDescription>Edited a few minutes ago by Maya Chen. Changes apply to the public changelog.</CardDescription>\n      </CardHeader>\n      <CardFooter className=\"flex flex-wrap items-center justify-between gap-3\">\n        <Button variant=\"soft\" tone=\"danger\" leadingIcon={<Trash weight=\"bold\" />}>\n          Delete draft\n        </Button>\n        <div className=\"flex items-center gap-2\">\n          <Button variant=\"ghost\" onClick={() => setState(\"idle\")}>\n            Cancel\n          </Button>\n          <Button\n            variant=\"solid\"\n            tone=\"accent\"\n            loading={state === \"saving\"}\n            leadingIcon={state === \"saved\" ? <Check weight=\"bold\" /> : <FloppyDisk weight=\"bold\" />}\n            onClick={save}\n          >\n            {state === \"saving\" ? \"Saving\" : state === \"saved\" ? \"Saved\" : \"Save changes\"}\n          </Button>\n        </div>\n      </CardFooter>\n    </Card>\n  )\n}",
  "ButtonStatesDemo": "import { ArrowRight, Plus } from \"@phosphor-icons/react\"\nimport { Button } from \"@glinui/ui\"\n\nexport function ButtonStatesDemo() {\n  return (\n    <div className=\"grid w-full max-w-2xl gap-5\">\n      <div className=\"flex flex-wrap items-end gap-3\">\n        <Button size=\"xs\">Extra small</Button>\n        <Button size=\"sm\">Small</Button>\n        <Button size=\"md\">Medium</Button>\n        <Button size=\"lg\">Large</Button>\n        <Button size=\"icon\" variant=\"outline\" aria-label=\"Add a member\">\n          <Plus weight=\"bold\" />\n        </Button>\n      </div>\n      <div className=\"flex flex-wrap items-center gap-3\">\n        <Button variant=\"solid\" tone=\"accent\" leadingIcon={<Plus weight=\"bold\" />}>\n          New project\n        </Button>\n        <Button variant=\"outline\" trailingIcon={<ArrowRight weight=\"bold\" />} iconNudge>\n          Continue\n        </Button>\n        <Button variant=\"solid\" tone=\"accent\" loading>\n          Publishing\n        </Button>\n        <Button variant=\"outline\" loading>\n          Syncing\n        </Button>\n        <Button disabled>Unavailable</Button>\n        <Button variant=\"solid\" tone=\"danger\" disabled>\n          Delete\n        </Button>\n      </div>\n    </div>\n  )\n}",
  "ButtonPageHeader": "import { DownloadSimple, Funnel, Plus } from \"@phosphor-icons/react\"\nimport { Button, Card, CardContent } from \"@glinui/ui\"\n\nexport function ButtonPageHeader() {\n  return (\n    <Card className=\"w-full max-w-3xl\">\n      <CardContent className=\"flex flex-wrap items-center justify-between gap-4\">\n        <div className=\"min-w-0\">\n          <h3 className=\"text-lg font-semibold text-foreground\">Invoices</h3>\n          <p className=\"text-sm text-[var(--color-muted)]\">48 invoices this quarter, 3 overdue.</p>\n        </div>\n        <div className=\"flex flex-wrap items-center gap-2\">\n          <Button variant=\"ghost\" leadingIcon={<Funnel weight=\"bold\" />}>\n            Filter\n          </Button>\n          <Button variant=\"outline\" leadingIcon={<DownloadSimple weight=\"bold\" />}>\n            Export CSV\n          </Button>\n          <Button variant=\"solid\" tone=\"accent\" leadingIcon={<Plus weight=\"bold\" />}>\n            New invoice\n          </Button>\n        </div>\n      </CardContent>\n    </Card>\n  )\n}",
  "ShimmerPricing": "import { ArrowRight, Check } from \"@phosphor-icons/react\"\nimport { Badge, Card, CardContent, CardDescription, CardHeader, CardTitle, ShimmerButton } from \"@glinui/ui\"\n\nexport function ShimmerPricing() {\n  return (\n    <Card className=\"w-full max-w-sm\">\n      <CardHeader>\n        <div className=\"flex items-center justify-between\">\n          <CardTitle>Pro</CardTitle>\n          <Badge tone=\"accent\" variant=\"soft\">Most popular</Badge>\n        </div>\n        <CardDescription>For teams shipping weekly.</CardDescription>\n      </CardHeader>\n      <CardContent className=\"space-y-4\">\n        <p className=\"text-foreground\">\n          <span className=\"text-4xl font-semibold tracking-tight\">$24</span>\n          <span className=\"text-sm text-[var(--color-muted)]\"> per seat, per month</span>\n        </p>\n        <ul className=\"space-y-2 text-sm text-[var(--color-muted)]\">\n          <li className=\"flex items-center gap-2\"><Check weight=\"bold\" className=\"size-4 text-[color:var(--tone-success-text)]\" />Unlimited projects</li>\n          <li className=\"flex items-center gap-2\"><Check weight=\"bold\" className=\"size-4 text-[color:var(--tone-success-text)]\" />Audit log and SSO</li>\n          <li className=\"flex items-center gap-2\"><Check weight=\"bold\" className=\"size-4 text-[color:var(--tone-success-text)]\" />Priority support</li>\n        </ul>\n        <ShimmerButton className=\"w-full\" trailingIcon={<ArrowRight weight=\"bold\" />}>\n          Start 14 day trial\n        </ShimmerButton>\n      </CardContent>\n    </Card>\n  )\n}",
  "RippleAddToCart": "\"use client\"\n\nimport { useState } from \"react\"\nimport { Lightning, ShoppingCart } from \"@phosphor-icons/react\"\nimport { Card, CardContent, CardFooter, RippleButton } from \"@glinui/ui\"\n\nexport function RippleAddToCart() {\n  const [count, setCount] = useState(0)\n  return (\n    <Card className=\"w-full max-w-sm\">\n      <CardContent className=\"flex items-center gap-4\">\n        <div\n          aria-hidden\n          className=\"grid size-16 shrink-0 place-items-center rounded-xl bg-gradient-to-br from-violet-500 to-sky-400 text-white\"\n        >\n          <Lightning weight=\"fill\" className=\"size-7\" />\n        </div>\n        <div className=\"min-w-0 flex-1\">\n          <p className=\"truncate font-medium text-foreground\">Studio keyboard, 75%</p>\n          <p className=\"text-sm text-[var(--color-muted)]\">$129.00, ships in 2 days</p>\n        </div>\n      </CardContent>\n      <CardFooter className=\"flex items-center justify-between gap-3\">\n        <span className=\"text-sm text-[var(--color-muted)]\" aria-live=\"polite\">\n          {count === 0 ? \"Your cart is empty\" : `${count} in your cart`}\n        </span>\n        <RippleButton leadingIcon={<ShoppingCart weight=\"bold\" />} onClick={() => setCount((value) => value + 1)}>\n          Add to cart\n        </RippleButton>\n      </CardFooter>\n    </Card>\n  )\n}",
  "PulsatingGoLive": "\"use client\"\n\nimport { useState } from \"react\"\nimport { Broadcast } from \"@phosphor-icons/react\"\nimport { Badge, Button, Card, CardDescription, CardFooter, CardHeader, CardTitle, PulsatingButton } from \"@glinui/ui\"\n\nexport function PulsatingGoLive() {\n  const [live, setLive] = useState(false)\n  return (\n    <Card className=\"w-full max-w-sm\">\n      <CardHeader>\n        <div className=\"flex items-center justify-between gap-3\">\n          <CardTitle>Friday product demo</CardTitle>\n          <Badge tone={live ? \"danger\" : \"neutral\"} variant=\"soft\" dot>\n            {live ? \"On air\" : \"Offline\"}\n          </Badge>\n        </div>\n        <CardDescription>Camera and microphone are ready. 128 people are waiting in the lobby.</CardDescription>\n      </CardHeader>\n      <CardFooter>\n        {live ? (\n          <Button variant=\"outline\" tone=\"danger\" className=\"w-full\" onClick={() => setLive(false)}>\n            End broadcast\n          </Button>\n        ) : (\n          <PulsatingButton className=\"w-full\" leadingIcon={<Broadcast weight=\"bold\" />} onClick={() => setLive(true)}>\n            Go live\n          </PulsatingButton>\n        )}\n      </CardFooter>\n    </Card>\n  )\n}",
  "LiquidUpgrade": "import { Cloud, Rocket } from \"@phosphor-icons/react\"\nimport { Card, CardContent, CardDescription, CardHeader, CardTitle, LiquidButton, Progress } from \"@glinui/ui\"\n\nexport function LiquidUpgrade() {\n  return (\n    <Card className=\"w-full max-w-sm\">\n      <CardHeader>\n        <div className=\"flex items-center gap-2\">\n          <Cloud weight=\"duotone\" className=\"size-5 text-[var(--color-accent)]\" />\n          <CardTitle>Storage almost full</CardTitle>\n        </div>\n        <CardDescription>You have used 18.6 GB of your 20 GB plan.</CardDescription>\n      </CardHeader>\n      <CardContent className=\"space-y-4\">\n        <Progress value={93} aria-label=\"Storage used\" />\n        <LiquidButton className=\"w-full\" leadingIcon={<Rocket weight=\"bold\" />}>\n          Upgrade to 200 GB\n        </LiquidButton>\n      </CardContent>\n    </Card>\n  )\n}",
  "MagneticHero": "import { ArrowRight } from \"@phosphor-icons/react\"\nimport { Badge, Button, MagneticCTA } from \"@glinui/ui\"\n\nexport function MagneticHero() {\n  return (\n    <section aria-label=\"Launch announcement\" className=\"flex w-full max-w-xl flex-col items-center gap-5 py-6 text-center\">\n      <Badge tone=\"accent\" variant=\"soft\">New: scheduled deploys</Badge>\n      <h3 className=\"text-3xl font-semibold tracking-tight text-foreground sm:text-4xl\">Ship on your own schedule</h3>\n      <p className=\"max-w-md text-sm text-[var(--color-muted)]\">\n        Queue a release for Tuesday morning and let the pipeline handle the rest. Rollbacks stay one click away.\n      </p>\n      <div className=\"flex flex-wrap items-center justify-center gap-3\">\n        <MagneticCTA size=\"lg\" variant=\"solid\" tone=\"accent\" trailingIcon={<ArrowRight weight=\"bold\" />}>\n          Book a demo\n        </MagneticCTA>\n        <Button size=\"lg\" variant=\"ghost\">\n          Read the changelog\n        </Button>\n      </div>\n    </section>\n  )\n}",
  "HoverButtonCta": "import { Card, CardDescription, CardFooter, CardHeader, CardTitle, InteractiveHoverButton } from \"@glinui/ui\"\n\nexport function HoverButtonCta() {\n  return (\n    <Card className=\"w-full max-w-md\">\n      <CardHeader>\n        <CardTitle>Join the beta</CardTitle>\n        <CardDescription>Early access to the new analytics workspace. Hover or focus the button to see it fill.</CardDescription>\n      </CardHeader>\n      <CardFooter className=\"flex flex-wrap items-center justify-between gap-3\">\n        <span className=\"text-sm text-[var(--color-muted)]\">1,240 teams already in</span>\n        <InteractiveHoverButton>Request access</InteractiveHoverButton>\n      </CardFooter>\n    </Card>\n  )\n}",
  "GenerateCompose": "import { Sparkle } from \"@phosphor-icons/react\"\nimport { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle, GenerateButton } from \"@glinui/ui\"\n\nexport function GenerateCompose() {\n  return (\n    <Card className=\"w-full max-w-md\">\n      <CardHeader>\n        <CardTitle>Product description</CardTitle>\n        <CardDescription>Draft copy for the Studio keyboard from its spec sheet. Press the button to start and again to stop.</CardDescription>\n      </CardHeader>\n      <CardContent>\n        <div className=\"rounded-lg border border-border/60 p-3 text-sm text-[var(--color-muted)]\">\n          75% layout, gasket mount, hot-swap switches, USB-C and Bluetooth, aluminum case in three finishes.\n        </div>\n      </CardContent>\n      <CardFooter className=\"flex items-center justify-between gap-3\">\n        <span className=\"text-sm text-[var(--color-muted)]\">Uses 1 credit</span>\n        <GenerateButton label=\"Generate copy\" generatingLabel=\"Writing\" leadingIcon={<Sparkle weight=\"fill\" />} />\n      </CardFooter>\n    </Card>\n  )\n}",
  "ButtonGroupToolbar": "\"use client\"\n\nimport { useState } from \"react\"\nimport { ArrowRight, Check } from \"@phosphor-icons/react\"\nimport { Button, ButtonGroup, ButtonGroupSeparator, Card, CardContent } from \"@glinui/ui\"\n\nexport function ButtonGroupToolbar() {\n  const [range, setRange] = useState(\"week\")\n  return (\n    <Card className=\"w-full max-w-xl\">\n      <CardContent className=\"flex flex-wrap items-center justify-between gap-3\">\n        <ButtonGroup aria-label=\"Time range\">\n          {[\"day\", \"week\", \"month\"].map((value) => (\n            <Button\n              key={value}\n              variant={range === value ? \"solid\" : \"outline\"}\n              aria-pressed={range === value}\n              onClick={() => setRange(value)}\n            >\n              {value === \"day\" ? \"Day\" : value === \"week\" ? \"Week\" : \"Month\"}\n            </Button>\n          ))}\n        </ButtonGroup>\n        <ButtonGroup aria-label=\"Pull request actions\" variant=\"outline\">\n          <Button leadingIcon={<Check weight=\"bold\" />}>Merge pull request</Button>\n          <ButtonGroupSeparator />\n          <Button size=\"icon\" aria-label=\"More merge options\">\n            <ArrowRight weight=\"bold\" className=\"rotate-90\" />\n          </Button>\n        </ButtonGroup>\n      </CardContent>\n    </Card>\n  )\n}",
  "CopyApiKey": "import { Card, CardContent, CardDescription, CardHeader, CardTitle, CopyButton } from \"@glinui/ui\"\n\nexport function CopyApiKey() {\n  return (\n    <Card className=\"w-full max-w-lg\">\n      <CardHeader>\n        <CardTitle>API key</CardTitle>\n        <CardDescription>Use this key to authenticate server requests. Treat it like a password.</CardDescription>\n      </CardHeader>\n      <CardContent className=\"space-y-3\">\n        <div className=\"flex items-center justify-between gap-3 rounded-lg border border-border/60 bg-[var(--surface-1)] px-3 py-2\">\n          <code className=\"truncate font-mono text-sm text-foreground\">glin_live_4f9a7c21b6e8</code>\n          <CopyButton value=\"glin_live_4f9a7c21b6e8\" variant=\"outline\" size=\"sm\" label=\"Copy key\" copiedLabel=\"Copied\" />\n        </div>\n        <div className=\"flex items-center justify-between gap-3 rounded-lg border border-border/60 bg-[var(--surface-1)] px-3 py-2\">\n          <code className=\"truncate font-mono text-sm text-foreground\">pnpm add @glinui/ui</code>\n          <CopyButton value=\"pnpm add @glinui/ui\" variant=\"ghost\" size=\"icon\" iconOnly label=\"Copy install command\" />\n        </div>\n      </CardContent>\n    </Card>\n  )\n}",
  "ToggleEditorToolbar": "import { BellRinging, TextAlignCenter, TextAlignLeft, TextAlignRight, TextB, TextItalic, TextUnderline } from \"@phosphor-icons/react\"\nimport { Card, CardContent, Toggle, ToggleGroup, ToggleGroupItem } from \"@glinui/ui\"\n\nexport function ToggleEditorToolbar() {\n  return (\n    <Card className=\"w-full max-w-lg\">\n      <CardContent className=\"space-y-4\">\n        <div role=\"toolbar\" aria-label=\"Text formatting\" className=\"flex flex-wrap items-center gap-2\">\n          <ToggleGroup type=\"multiple\" defaultValue={[\"bold\", \"italic\"]} aria-label=\"Text style\">\n            <ToggleGroupItem value=\"bold\" aria-label=\"Bold\"><TextB weight=\"bold\" /></ToggleGroupItem>\n            <ToggleGroupItem value=\"italic\" aria-label=\"Italic\"><TextItalic weight=\"bold\" /></ToggleGroupItem>\n            <ToggleGroupItem value=\"underline\" aria-label=\"Underline\"><TextUnderline weight=\"bold\" /></ToggleGroupItem>\n          </ToggleGroup>\n          <ToggleGroup type=\"single\" defaultValue=\"left\" aria-label=\"Alignment\">\n            <ToggleGroupItem value=\"left\" aria-label=\"Align left\"><TextAlignLeft /></ToggleGroupItem>\n            <ToggleGroupItem value=\"center\" aria-label=\"Align center\"><TextAlignCenter /></ToggleGroupItem>\n            <ToggleGroupItem value=\"right\" aria-label=\"Align right\"><TextAlignRight /></ToggleGroupItem>\n          </ToggleGroup>\n          <Toggle aria-label=\"Notify subscribers\" defaultPressed variant=\"soft\">\n            <BellRinging weight=\"bold\" />\n          </Toggle>\n        </div>\n        <p className=\"rounded-lg border border-border/60 bg-[var(--surface-1)] p-3 text-sm text-foreground\">\n          Weekly digest: three launches, one deprecation and a new way to schedule deploys.\n        </p>\n      </CardContent>\n    </Card>\n  )\n}",
  "ToggleViewSwitcher": "\"use client\"\n\nimport { useState } from \"react\"\nimport { Card, CardContent, CardHeader, CardTitle, ToggleGroup, ToggleGroupItem } from \"@glinui/ui\"\n\nexport function ToggleViewSwitcher() {\n  const [view, setView] = useState(\"list\")\n  const rows = [\"Atlas redesign\", \"Billing migration\", \"Mobile onboarding\"]\n  return (\n    <Card className=\"w-full max-w-lg\">\n      <CardHeader>\n        <div className=\"flex items-center justify-between gap-3\">\n          <CardTitle>Projects</CardTitle>\n          <ToggleGroup\n            type=\"single\"\n            value={view}\n            onValueChange={(next) => next && setView(next)}\n            aria-label=\"Layout\"\n            size=\"sm\"\n          >\n            <ToggleGroupItem value=\"list\">List</ToggleGroupItem>\n            <ToggleGroupItem value=\"grid\">Grid</ToggleGroupItem>\n          </ToggleGroup>\n        </div>\n      </CardHeader>\n      <CardContent>\n        <ul className={view === \"grid\" ? \"grid grid-cols-3 gap-2\" : \"grid gap-2\"}>\n          {rows.map((row) => (\n            <li key={row} className=\"rounded-lg border border-border/60 bg-[var(--surface-1)] px-3 py-2 text-sm text-foreground\">\n              {row}\n            </li>\n          ))}\n        </ul>\n      </CardContent>\n    </Card>\n  )\n}",
  "ToggleStepper": "\"use client\"\n\nimport { useState } from \"react\"\nimport { Minus, Plus } from \"@phosphor-icons/react\"\nimport { Button, ButtonGroup } from \"@glinui/ui\"\n\nexport function ToggleStepper() {\n  const [qty, setQty] = useState(2)\n  return (\n    <ButtonGroup aria-label=\"Quantity\" variant=\"outline\">\n      <Button size=\"icon\" aria-label=\"Decrease quantity\" onClick={() => setQty((value) => Math.max(1, value - 1))}>\n        <Minus weight=\"bold\" />\n      </Button>\n      <Button aria-live=\"polite\" tabIndex={-1} className=\"min-w-12 tabular-nums\">{qty}</Button>\n      <Button size=\"icon\" aria-label=\"Increase quantity\" onClick={() => setQty((value) => value + 1)}>\n        <Plus weight=\"bold\" />\n      </Button>\n    </ButtonGroup>\n  )\n}",
  "GlassQuickSettings": "import { Airplane, Bluetooth, Moon, Palette, WifiHigh } from \"@phosphor-icons/react\"\nimport { GlassToggle } from \"@glinui/ui\"\n\nexport function GlassQuickSettings() {\n  return (\n    <section\n      aria-label=\"Quick settings\"\n      className=\"w-full max-w-xs space-y-1 rounded-2xl border border-white/25 bg-white/10 p-2 text-white backdrop-blur-xl\"\n    >\n      {[\n        { id: \"wifi\", label: \"Wi-Fi\", note: \"Studio-5G\", icon: WifiHigh, on: true },\n        { id: \"bt\", label: \"Bluetooth\", note: \"2 devices\", icon: Bluetooth, on: true },\n        { id: \"dnd\", label: \"Focus\", note: \"Until 5 PM\", icon: Moon, on: false },\n        { id: \"air\", label: \"Airplane mode\", note: \"Off\", icon: Airplane, on: false },\n        { id: \"theme\", label: \"Night shift\", note: \"Warm tone\", icon: Palette, on: true }\n      ].map(({ id, label, note, icon: Icon, on }) => (\n        <div key={id} className=\"flex items-center gap-3 rounded-xl px-3 py-2.5\">\n          <Icon weight=\"bold\" className=\"size-5 shrink-0\" aria-hidden />\n          <label htmlFor={`gt-${id}`} className=\"min-w-0 flex-1\">\n            <span className=\"block text-sm font-medium\">{label}</span>\n            <span className=\"block text-xs text-white/80\">{note}</span>\n          </label>\n          <GlassToggle id={`gt-${id}`} defaultChecked={on} />\n        </div>\n      ))}\n    </section>\n  )\n}",
  "InputSignUpForm": "\"use client\"\n\nimport { useState } from \"react\"\nimport { CheckCircle } from \"@phosphor-icons/react\"\nimport { Button, Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle, Field, FieldControl, FieldDescription, FieldError, FieldLabel, Input } from \"@glinui/ui\"\n\nexport function InputSignUpForm() {\n  const [email, setEmail] = useState(\"maya@acme\")\n  const [handle, setHandle] = useState(\"mayachen\")\n  const emailInvalid = email.length > 0 && !/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email)\n  const handleTaken = handle === \"admin\"\n  const handleOk = handle.length >= 3 && !handleTaken\n\n  return (\n    <Card className=\"w-full max-w-md\">\n      <CardHeader>\n        <CardTitle>Create your account</CardTitle>\n        <CardDescription>Free for teams up to five people. No card needed.</CardDescription>\n      </CardHeader>\n      <CardContent>\n        <form className=\"grid gap-4\" onSubmit={(event) => event.preventDefault()} noValidate>\n          <Field>\n            <FieldLabel>Full name</FieldLabel>\n            <FieldControl><Input autoComplete=\"name\" defaultValue=\"Maya Chen\" /></FieldControl>\n            <FieldDescription>Shown on invoices and in your team directory.</FieldDescription>\n          </Field>\n          <Field invalid={emailInvalid}>\n            <FieldLabel>Work email</FieldLabel>\n            <FieldControl>\n              <Input type=\"email\" autoComplete=\"email\" value={email} onChange={(event) => setEmail(event.target.value)} />\n            </FieldControl>\n            {emailInvalid ? <FieldError>Enter a full address like maya@acme.com.</FieldError> : null}\n          </Field>\n          <Field invalid={handleTaken}>\n            <FieldLabel>Username</FieldLabel>\n            <FieldControl>\n              <Input autoComplete=\"username\" value={handle} onChange={(event) => setHandle(event.target.value.trim())} />\n            </FieldControl>\n            {handleTaken ? <FieldError>That username is taken. Try another.</FieldError> : null}\n            {handleOk ? (\n              <p className=\"flex items-center gap-1.5 text-sm text-[color:var(--tone-success-text)]\">\n                <CheckCircle weight=\"fill\" className=\"size-4\" aria-hidden />\n                glin.app/{handle} is available\n              </p>\n            ) : null}\n          </Field>\n        </form>\n      </CardContent>\n      <CardFooter>\n        <Button variant=\"solid\" tone=\"accent\" className=\"w-full\" disabled={emailInvalid || handleTaken}>\n          Create account\n        </Button>\n      </CardFooter>\n    </Card>\n  )\n}",
  "InputStatesDemo": "import { Field, FieldControl, FieldError, FieldLabel, Input } from \"@glinui/ui\"\n\nexport function InputStatesDemo() {\n  return (\n    <div className=\"grid w-full max-w-2xl gap-4 sm:grid-cols-2\">\n      <Field>\n        <FieldLabel>Default</FieldLabel>\n        <FieldControl><Input placeholder=\"Search projects\" /></FieldControl>\n      </Field>\n      <Field>\n        <FieldLabel>With value</FieldLabel>\n        <FieldControl><Input defaultValue=\"Atlas redesign\" /></FieldControl>\n      </Field>\n      <Field invalid>\n        <FieldLabel>Invalid</FieldLabel>\n        <FieldControl><Input defaultValue=\"not-an-email\" /></FieldControl>\n        <FieldError>Enter a valid email address.</FieldError>\n      </Field>\n      <Field disabled>\n        <FieldLabel>Disabled</FieldLabel>\n        <FieldControl><Input defaultValue=\"Locked by an admin\" /></FieldControl>\n      </Field>\n      <Field>\n        <FieldLabel>Small</FieldLabel>\n        <FieldControl><Input size=\"sm\" placeholder=\"Compact\" /></FieldControl>\n      </Field>\n      <Field>\n        <FieldLabel>Large</FieldLabel>\n        <FieldControl><Input size=\"lg\" placeholder=\"Roomy\" /></FieldControl>\n      </Field>\n    </div>\n  )\n}",
  "TextareaFeedbackForm": "\"use client\"\n\nimport { useState } from \"react\"\nimport { Button, Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle, Field, FieldControl, FieldDescription, FieldLabel, Select, Textarea } from \"@glinui/ui\"\n\nexport function TextareaFeedbackForm() {\n  const [message, setMessage] = useState(\"The export button is hidden on narrow screens, so I could not download my invoices from my phone.\")\n  const limit = 280\n  return (\n    <Card className=\"w-full max-w-md\">\n      <CardHeader>\n        <CardTitle>Send feedback</CardTitle>\n        <CardDescription>Tell us what is slowing you down. A person reads every message.</CardDescription>\n      </CardHeader>\n      <CardContent className=\"grid gap-4\">\n        <Field>\n          <FieldLabel>Topic</FieldLabel>\n          <FieldControl>\n            <Select\n              defaultValue=\"bug\"\n              options={[\n                { value: \"bug\", label: \"Something is broken\" },\n                { value: \"idea\", label: \"Feature idea\" },\n                { value: \"billing\", label: \"Billing question\" }\n              ]}\n            />\n          </FieldControl>\n        </Field>\n        <Field>\n          <FieldLabel>Message</FieldLabel>\n          <FieldControl>\n            <Textarea rows={4} maxLength={limit} value={message} onChange={(event) => setMessage(event.target.value)} />\n          </FieldControl>\n          <FieldDescription>{limit - message.length} characters left.</FieldDescription>\n        </Field>\n      </CardContent>\n      <CardFooter className=\"flex items-center justify-end gap-2\">\n        <Button variant=\"ghost\" onClick={() => setMessage(\"\")}>Clear</Button>\n        <Button variant=\"solid\" tone=\"accent\" disabled={message.trim().length === 0}>Send feedback</Button>\n      </CardFooter>\n    </Card>\n  )\n}",
  "SelectPreferences": "import { Card, CardContent, CardDescription, CardHeader, CardTitle, Field, FieldControl, FieldDescription, FieldLabel, Select } from \"@glinui/ui\"\n\nexport function SelectPreferences() {\n  return (\n    <Card className=\"w-full max-w-xl\">\n      <CardHeader>\n        <CardTitle>Preferences</CardTitle>\n        <CardDescription>Applies to every workspace you belong to.</CardDescription>\n      </CardHeader>\n      <CardContent className=\"divide-y divide-border/60\">\n        <Field orientation=\"responsive\" className=\"py-3 first:pt-0\">\n          <div className=\"grid flex-auto gap-0.5\">\n            <FieldLabel>Language</FieldLabel>\n            <FieldDescription>Used for menus and emails.</FieldDescription>\n          </div>\n          <FieldControl>\n            <Select\n              className=\"md:w-48\"\n              defaultValue=\"en\"\n              options={[\n                { value: \"en\", label: \"English\" },\n                { value: \"de\", label: \"Deutsch\" },\n                { value: \"fr\", label: \"Francais\" },\n                { value: \"ja\", label: \"Japanese\" }\n              ]}\n            />\n          </FieldControl>\n        </Field>\n        <Field orientation=\"responsive\" className=\"py-3\">\n          <div className=\"grid flex-auto gap-0.5\">\n            <FieldLabel>Time zone</FieldLabel>\n            <FieldDescription>Schedules and digests follow it.</FieldDescription>\n          </div>\n          <FieldControl>\n            <Select\n              className=\"md:w-48\"\n              defaultValue=\"pt\"\n              options={[\n                { value: \"pt\", label: \"Pacific (UTC-8)\" },\n                { value: \"et\", label: \"Eastern (UTC-5)\" },\n                { value: \"cet\", label: \"Central Europe (UTC+1)\" },\n                { value: \"ist\", label: \"India (UTC+5:30)\" }\n              ]}\n            />\n          </FieldControl>\n        </Field>\n        <Field orientation=\"responsive\" className=\"py-3 last:pb-0\">\n          <div className=\"grid flex-auto gap-0.5\">\n            <FieldLabel>Date format</FieldLabel>\n            <FieldDescription>How dates appear in tables.</FieldDescription>\n          </div>\n          <FieldControl>\n            <Select\n              className=\"md:w-48\"\n              defaultValue=\"iso\"\n              options={[\n                { value: \"iso\", label: \"2026-10-07\" },\n                { value: \"us\", label: \"10/07/2026\" },\n                { value: \"eu\", label: \"07/10/2026\" }\n              ]}\n            />\n          </FieldControl>\n        </Field>\n      </CardContent>\n    </Card>\n  )\n}",
  "CheckboxColumns": "\"use client\"\n\nimport { useState } from \"react\"\nimport { Button, Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle, Checkbox } from \"@glinui/ui\"\n\nexport function CheckboxColumns() {\n  const columns = [\"Invoice number\", \"Customer\", \"Amount\", \"Status\", \"Due date\"]\n  const [selected, setSelected] = useState<string[]>([\"Invoice number\", \"Customer\", \"Amount\"])\n  const all = selected.length === columns.length\n  return (\n    <Card className=\"w-full max-w-sm\">\n      <CardHeader>\n        <CardTitle>Export columns</CardTitle>\n        <CardDescription>{selected.length} of {columns.length} included in the CSV.</CardDescription>\n      </CardHeader>\n      <CardContent>\n        <fieldset className=\"grid gap-3 border-0 p-0\">\n          <legend className=\"sr-only\">Columns to export</legend>\n          <label className=\"flex items-center gap-2.5 border-b border-border/60 pb-3 text-sm font-medium text-foreground\">\n            <Checkbox\n              checked={all ? true : selected.length === 0 ? false : \"indeterminate\"}\n              onCheckedChange={(next) => setSelected(next === true ? columns : [])}\n            />\n            Select all\n          </label>\n          {columns.map((column) => (\n            <label key={column} className=\"flex items-center gap-2.5 text-sm text-foreground\">\n              <Checkbox\n                checked={selected.includes(column)}\n                onCheckedChange={(next) =>\n                  setSelected((current) => (next === true ? [...current, column] : current.filter((item) => item !== column)))\n                }\n              />\n              {column}\n            </label>\n          ))}\n        </fieldset>\n      </CardContent>\n      <CardFooter>\n        <Button variant=\"solid\" tone=\"accent\" className=\"w-full\" disabled={selected.length === 0}>Export CSV</Button>\n      </CardFooter>\n    </Card>\n  )\n}",
  "RadioPlanPicker": "import { Card, CardContent, CardDescription, CardHeader, CardTitle, RadioGroup, RadioGroupItem } from \"@glinui/ui\"\n\nexport function RadioPlanPicker() {\n  const plans = [\n    { value: \"starter\", name: \"Starter\", price: \"$0\", note: \"Up to 3 projects\" },\n    { value: \"pro\", name: \"Pro\", price: \"$24\", note: \"Unlimited projects, SSO\" },\n    { value: \"scale\", name: \"Scale\", price: \"$96\", note: \"Audit log, 99.9% uptime SLA\" }\n  ]\n  return (\n    <Card className=\"w-full max-w-md\">\n      <CardHeader>\n        <CardTitle>Choose a plan</CardTitle>\n        <CardDescription>Billed monthly. Change or cancel any time.</CardDescription>\n      </CardHeader>\n      <CardContent>\n        <RadioGroup defaultValue=\"pro\" aria-label=\"Plan\" className=\"grid gap-2\">\n          {plans.map((plan) => (\n            <label\n              key={plan.value}\n              className=\"flex cursor-pointer items-center gap-3 rounded-lg border border-border/60 px-3 py-3 has-[[data-state=checked]]:border-[var(--color-accent)] has-[[data-state=checked]]:bg-[var(--surface-1)]\"\n            >\n              <RadioGroupItem value={plan.value} />\n              <span className=\"min-w-0 flex-1\">\n                <span className=\"block text-sm font-medium text-foreground\">{plan.name}</span>\n                <span className=\"block text-xs text-[var(--color-muted)]\">{plan.note}</span>\n              </span>\n              <span className=\"text-sm font-medium tabular-nums text-foreground\">{plan.price}<span className=\"text-xs font-normal text-[var(--color-muted)]\">/seat</span></span>\n            </label>\n          ))}\n        </RadioGroup>\n      </CardContent>\n    </Card>\n  )\n}",
  "SliderPriceFilter": "\"use client\"\n\nimport { useState } from \"react\"\nimport { Button, Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle, Label, Slider } from \"@glinui/ui\"\n\nexport function SliderPriceFilter() {\n  const [range, setRange] = useState([40, 220])\n  const [volume, setVolume] = useState([65])\n  const results = Math.max(0, Math.round((range[1] - range[0]) * 0.42))\n  return (\n    <Card className=\"w-full max-w-sm\">\n      <CardHeader>\n        <CardTitle>Filter listings</CardTitle>\n        <CardDescription>{results} stays match your budget.</CardDescription>\n      </CardHeader>\n      <CardContent className=\"grid gap-6\">\n        <div className=\"grid gap-3\">\n          <div className=\"flex items-baseline justify-between\">\n            <Label htmlFor=\"price-range\">Price per night</Label>\n            <output htmlFor=\"price-range\" className=\"text-sm font-medium tabular-nums text-foreground\">\n              ${range[0]} to ${range[1]}\n            </output>\n          </div>\n          <Slider id=\"price-range\" value={range} onValueChange={setRange} min={0} max={400} step={10} aria-label=\"Price range\" />\n        </div>\n        <div className=\"grid gap-3\">\n          <div className=\"flex items-baseline justify-between\">\n            <Label>Preview volume</Label>\n            <span className=\"text-sm tabular-nums text-[var(--color-muted)]\">{volume[0]}%</span>\n          </div>\n          <Slider value={volume} onValueChange={setVolume} max={100} step={1} aria-label=\"Preview volume\" />\n        </div>\n      </CardContent>\n      <CardFooter className=\"flex justify-between\">\n        <Button variant=\"ghost\" onClick={() => { setRange([40, 220]); setVolume([65]) }}>Reset</Button>\n        <Button variant=\"solid\" tone=\"accent\">Show {results} stays</Button>\n      </CardFooter>\n    </Card>\n  )\n}",
  "SwitchNotifications": "import { Card, CardContent, CardDescription, CardHeader, CardTitle, Switch } from \"@glinui/ui\"\n\nexport function SwitchNotifications() {\n  const items = [\n    { id: \"mentions\", label: \"Mentions and replies\", note: \"When someone tags you in a thread.\", on: true },\n    { id: \"digest\", label: \"Weekly digest\", note: \"A Monday summary of what shipped.\", on: true },\n    { id: \"deploys\", label: \"Deploy failures\", note: \"Immediate email when a build fails.\", on: true },\n    { id: \"marketing\", label: \"Product news\", note: \"Occasional updates about new features.\", on: false }\n  ]\n  return (\n    <Card className=\"w-full max-w-lg\">\n      <CardHeader>\n        <CardTitle>Email notifications</CardTitle>\n        <CardDescription>Choose what lands in your inbox.</CardDescription>\n      </CardHeader>\n      <CardContent className=\"divide-y divide-border/60\">\n        {items.map((item) => (\n          <div key={item.id} className=\"flex items-center justify-between gap-4 py-3 first:pt-0 last:pb-0\">\n            <div className=\"min-w-0\">\n              <label htmlFor={`sw-${item.id}`} className=\"block text-sm font-medium text-foreground\">{item.label}</label>\n              <p id={`sw-${item.id}-note`} className=\"text-sm text-[var(--color-muted)]\">{item.note}</p>\n            </div>\n            <Switch id={`sw-${item.id}`} aria-describedby={`sw-${item.id}-note`} defaultChecked={item.on} />\n          </div>\n        ))}\n      </CardContent>\n    </Card>\n  )\n}",
  "ComboboxFrameworkPicker": "\"use client\"\n\nimport { useState } from \"react\"\nimport { Button, Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle, Combobox, Field, FieldControl, FieldLabel } from \"@glinui/ui\"\nimport { BrandIcon } from \"@/components/brand/brand-icon\"\n\nexport function ComboboxFrameworkPicker() {\n  const frameworks = [\n    { value: \"nextjs\", label: \"Next.js\", keywords: [\"react\", \"vercel\"] },\n    { value: \"remix\", label: \"Remix\", keywords: [\"react\"] },\n    { value: \"astro\", label: \"Astro\", keywords: [\"islands\"] },\n    { value: \"nuxt\", label: \"Nuxt\", keywords: [\"vue\"] },\n    { value: \"vite\", label: \"Vite\", keywords: [\"spa\"] }\n  ] as const\n  const [value, setValue] = useState(\"nextjs\")\n  const current = frameworks.find((item) => item.value === value)\n  return (\n    <Card className=\"w-full max-w-md\">\n      <CardHeader>\n        <CardTitle>New project</CardTitle>\n        <CardDescription>Pick the framework we should scaffold. Type to filter the list.</CardDescription>\n      </CardHeader>\n      <CardContent className=\"grid gap-4\">\n        <Field>\n          <FieldLabel>Framework</FieldLabel>\n          <FieldControl>\n            <Combobox\n              options={frameworks.map((item) => ({ ...item, keywords: [...item.keywords] }))}\n              value={value}\n              onValueChange={setValue}\n              placeholder=\"Select a framework\"\n              searchPlaceholder=\"Search frameworks\"\n              aria-label=\"Framework\"\n            />\n          </FieldControl>\n        </Field>\n        <div className=\"flex flex-wrap items-center gap-2\" role=\"group\" aria-label=\"Frameworks\">\n          {frameworks.map((item) => (\n            <button\n              key={item.value}\n              type=\"button\"\n              aria-pressed={item.value === value}\n              onClick={() => setValue(item.value)}\n              className=\"flex items-center gap-2 rounded-full border border-border/60 px-3 py-1.5 text-sm text-foreground outline-none transition-colors hover:bg-[var(--surface-1)] focus-visible:ring-2 focus-visible:ring-[var(--color-accent)] aria-pressed:border-[var(--color-accent)] aria-pressed:bg-[var(--surface-1)]\"\n            >\n              <BrandIcon name={item.value} size={16} />\n              {item.label}\n            </button>\n          ))}\n        </div>\n      </CardContent>\n      <CardFooter className=\"flex items-center justify-between gap-3\">\n        <span className=\"text-sm text-[var(--color-muted)]\">{current ? `${current.label} starter selected` : \"Nothing selected\"}</span>\n        <Button variant=\"solid\" tone=\"accent\" disabled={!current}>Create project</Button>\n      </CardFooter>\n    </Card>\n  )\n}",
  "InputGroupShare": "import { Link as LinkIcon, MagnifyingGlass } from \"@phosphor-icons/react\"\nimport { Card, CardContent, CardDescription, CardHeader, CardTitle, InputGroup, InputGroupAddon, InputGroupButton, InputGroupInput, InputGroupText, Kbd } from \"@glinui/ui\"\n\nexport function InputGroupShare() {\n  return (\n    <Card className=\"w-full max-w-md\">\n      <CardHeader>\n        <CardTitle>Share this board</CardTitle>\n        <CardDescription>Anyone with the link can view. Only members can comment.</CardDescription>\n      </CardHeader>\n      <CardContent className=\"grid gap-4\">\n        <InputGroup>\n          <InputGroupAddon><LinkIcon /></InputGroupAddon>\n          <InputGroupInput aria-label=\"Share link\" readOnly defaultValue=\"glin.app/b/atlas-roadmap\" />\n          <InputGroupAddon align=\"inline-end\">\n            <InputGroupButton variant=\"ghost\">Copy</InputGroupButton>\n          </InputGroupAddon>\n        </InputGroup>\n        <InputGroup>\n          <InputGroupAddon><InputGroupText>https://</InputGroupText></InputGroupAddon>\n          <InputGroupInput aria-label=\"Custom domain\" defaultValue=\"roadmap\" />\n          <InputGroupAddon align=\"inline-end\"><InputGroupText>.glin.app</InputGroupText></InputGroupAddon>\n        </InputGroup>\n        <InputGroup>\n          <InputGroupAddon><MagnifyingGlass /></InputGroupAddon>\n          <InputGroupInput aria-label=\"Invite by email\" placeholder=\"Invite by email\" />\n          <InputGroupAddon align=\"inline-end\"><Kbd>Enter</Kbd></InputGroupAddon>\n        </InputGroup>\n      </CardContent>\n    </Card>\n  )\n}",
  "InputOtpVerify": "\"use client\"\n\nimport { useEffect, useState } from \"react\"\nimport { EnvelopeSimple, ShieldCheck } from \"@phosphor-icons/react\"\nimport { Button, Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle, InputOTP, InputOTPGroup, InputOTPSeparator, InputOTPSlot } from \"@glinui/ui\"\n\nexport function InputOtpVerify() {\n  const [code, setCode] = useState(\"482\")\n  const [seconds, setSeconds] = useState(24)\n  const [verified, setVerified] = useState(false)\n  useEffect(() => {\n    if (seconds <= 0) return\n    const id = setTimeout(() => setSeconds((value) => value - 1), 1000)\n    return () => clearTimeout(id)\n  }, [seconds])\n\n  return (\n    <Card className=\"w-full max-w-sm\">\n      <CardHeader>\n        <div className=\"flex size-10 items-center justify-center rounded-full bg-[var(--surface-1)] text-[var(--color-accent)]\">\n          <EnvelopeSimple weight=\"duotone\" className=\"size-5\" aria-hidden />\n        </div>\n        <CardTitle>Check your email</CardTitle>\n        <CardDescription>We sent a 6 digit code to maya@acme.com. It expires in 10 minutes.</CardDescription>\n      </CardHeader>\n      <CardContent className=\"grid gap-3\">\n        <InputOTP\n          maxLength={6}\n          value={code}\n          onChange={setCode}\n          onComplete={() => setVerified(true)}\n          aria-label=\"Verification code\"\n        >\n          <InputOTPGroup>\n            {[0, 1, 2].map((index) => <InputOTPSlot key={index} index={index} />)}\n          </InputOTPGroup>\n          <InputOTPSeparator />\n          <InputOTPGroup>\n            {[3, 4, 5].map((index) => <InputOTPSlot key={index} index={index} />)}\n          </InputOTPGroup>\n        </InputOTP>\n        <p className=\"min-h-5 text-sm text-[var(--color-muted)]\" aria-live=\"polite\">\n          {verified ? (\n            <span className=\"flex items-center gap-1.5 text-[color:var(--tone-success-text)]\">\n              <ShieldCheck weight=\"fill\" className=\"size-4\" aria-hidden />\n              Email verified\n            </span>\n          ) : (\n            \"Paste works too. The code fills every box.\"\n          )}\n        </p>\n      </CardContent>\n      <CardFooter className=\"flex items-center justify-between gap-3\">\n        <Button\n          variant=\"ghost\"\n          size=\"sm\"\n          disabled={seconds > 0}\n          onClick={() => { setSeconds(30); setCode(\"\"); setVerified(false) }}\n        >\n          {seconds > 0 ? `Resend in ${seconds}s` : \"Resend code\"}\n        </Button>\n        <Button variant=\"solid\" tone=\"accent\" disabled={code.length < 6}>Verify</Button>\n      </CardFooter>\n    </Card>\n  )\n}",
  "FieldCheckoutForm": "import { CreditCard } from \"@phosphor-icons/react\"\nimport { Button, Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle, Checkbox, Field, FieldControl, FieldDescription, FieldError, FieldGroup, FieldLabel, FieldLegend, FieldSet, Input, InputGroup, InputGroupAddon, InputGroupInput } from \"@glinui/ui\"\n\nexport function FieldCheckoutForm() {\n  return (\n    <Card className=\"w-full max-w-xl\">\n      <CardHeader>\n        <CardTitle>Checkout</CardTitle>\n        <CardDescription>Studio keyboard, 75%. $129.00 with free shipping.</CardDescription>\n      </CardHeader>\n      <CardContent>\n        <form className=\"grid gap-6\" onSubmit={(event) => event.preventDefault()}>\n          <FieldSet>\n            <FieldLegend>Contact</FieldLegend>\n            <FieldGroup>\n              <Field>\n                <FieldLabel>Email</FieldLabel>\n                <FieldControl><Input type=\"email\" autoComplete=\"email\" defaultValue=\"maya@acme.com\" /></FieldControl>\n                <FieldDescription>We send the receipt and tracking here.</FieldDescription>\n              </Field>\n            </FieldGroup>\n          </FieldSet>\n          <FieldSet>\n            <FieldLegend>Shipping</FieldLegend>\n            <FieldGroup>\n              <Field>\n                <FieldLabel>Street address</FieldLabel>\n                <FieldControl><Input autoComplete=\"street-address\" defaultValue=\"410 Alder Street\" /></FieldControl>\n              </Field>\n              <div className=\"grid gap-4 sm:grid-cols-2\">\n                <Field>\n                  <FieldLabel>City</FieldLabel>\n                  <FieldControl><Input autoComplete=\"address-level2\" defaultValue=\"Portland\" /></FieldControl>\n                </Field>\n                <Field invalid>\n                  <FieldLabel>Postal code</FieldLabel>\n                  <FieldControl><Input autoComplete=\"postal-code\" defaultValue=\"972\" /></FieldControl>\n                  <FieldError>Enter a 5 digit ZIP code.</FieldError>\n                </Field>\n              </div>\n            </FieldGroup>\n          </FieldSet>\n          <FieldSet>\n            <FieldLegend>Payment</FieldLegend>\n            <FieldGroup>\n              <Field>\n                <FieldLabel>Card number</FieldLabel>\n                <FieldControl>\n                  <InputGroup>\n                    <InputGroupAddon><CreditCard /></InputGroupAddon>\n                    <InputGroupInput inputMode=\"numeric\" autoComplete=\"cc-number\" placeholder=\"4242 4242 4242 4242\" />\n                  </InputGroup>\n                </FieldControl>\n              </Field>\n              <div className=\"grid grid-cols-2 gap-4\">\n                <Field>\n                  <FieldLabel>Expiry</FieldLabel>\n                  <FieldControl><Input autoComplete=\"cc-exp\" placeholder=\"MM / YY\" /></FieldControl>\n                </Field>\n                <Field>\n                  <FieldLabel>CVC</FieldLabel>\n                  <FieldControl><Input autoComplete=\"cc-csc\" placeholder=\"123\" /></FieldControl>\n                </Field>\n              </div>\n              <label className=\"flex items-center gap-2.5 text-sm text-foreground\">\n                <Checkbox defaultChecked />\n                Billing address is the same as shipping\n              </label>\n            </FieldGroup>\n          </FieldSet>\n        </form>\n      </CardContent>\n      <CardFooter>\n        <Button variant=\"solid\" tone=\"accent\" className=\"w-full\">Pay $129.00</Button>\n      </CardFooter>\n    </Card>\n  )\n}",
  "LabelPairings": "import { Card, CardContent, CardDescription, CardHeader, CardTitle, Checkbox, Input, Label, Switch, Textarea } from \"@glinui/ui\"\n\nexport function LabelPairings() {\n  return (\n    <Card className=\"w-full max-w-md\">\n      <CardHeader>\n        <CardTitle>Invite a teammate</CardTitle>\n        <CardDescription>Labels name a control for everyone, including screen readers.</CardDescription>\n      </CardHeader>\n      <CardContent className=\"grid gap-4\">\n        <div className=\"grid gap-1.5\">\n          <Label htmlFor=\"invite-email\">\n            Email address <span className=\"text-[color:var(--tone-danger-text)]\" aria-hidden>*</span>\n          </Label>\n          <Input id=\"invite-email\" type=\"email\" required placeholder=\"jordan@acme.com\" />\n        </div>\n        <div className=\"grid gap-1.5\">\n          <Label htmlFor=\"invite-note\">\n            Note <span className=\"text-xs font-normal text-[var(--color-muted)]\">(optional)</span>\n          </Label>\n          <Textarea id=\"invite-note\" rows={2} placeholder=\"Say hi, share context\" />\n        </div>\n        <div className=\"flex items-center gap-2.5\">\n          <Checkbox id=\"invite-admin\" />\n          <Label htmlFor=\"invite-admin\">Make this person an admin</Label>\n        </div>\n        <div className=\"flex items-center justify-between gap-3\">\n          <Label htmlFor=\"invite-copy\">Send me a copy</Label>\n          <Switch id=\"invite-copy\" defaultChecked />\n        </div>\n      </CardContent>\n    </Card>\n  )\n}",
  "PromptComposer": "\"use client\"\n\nimport { useState } from \"react\"\nimport { Paperclip, Plus } from \"@phosphor-icons/react\"\nimport { Attachment, Badge, Button, PromptInput } from \"@glinui/ui\"\n\nexport function PromptComposer() {\n  const library = [\n    { name: \"q3-report.pdf\", size: 482000, type: \"application/pdf\" },\n    { name: \"metrics.csv\", size: 96400, type: \"text/csv\" },\n    { name: \"launch-notes.md\", size: 7800, type: \"text/markdown\" }\n  ]\n  const [files, setFiles] = useState(library.slice(0, 2))\n  const [thread, setThread] = useState<string[]>([])\n  const next = library.find((file) => !files.some((item) => item.name === file.name))\n\n  return (\n    <div className=\"flex w-full max-w-xl flex-col gap-3\">\n      {thread.length > 0 ? (\n        <ul className=\"grid gap-2\" aria-label=\"Sent messages\">\n          {thread.map((message, index) => (\n            <li key={`${message}-${index}`} className=\"ms-auto max-w-[85%] rounded-xl bg-[var(--color-accent)] px-3 py-2 text-sm text-[var(--color-accent-foreground)]\">\n              {message}\n            </li>\n          ))}\n        </ul>\n      ) : null}\n      <PromptInput\n        label=\"Message\"\n        placeholder=\"Ask about the attached files\"\n        defaultValue=\"Summarize the main risks in these files and list three follow-ups.\"\n        attachments={\n          files.length > 0 ? (\n            <div className=\"flex flex-wrap gap-2\">\n              {files.map((file) => (\n                <Attachment\n                  key={file.name}\n                  name={file.name}\n                  size={file.size}\n                  type={file.type}\n                  onRemove={() => setFiles((current) => current.filter((item) => item.name !== file.name))}\n                />\n              ))}\n            </div>\n          ) : null\n        }\n        actions={\n          <Button\n            type=\"button\"\n            variant=\"ghost\"\n            size=\"sm\"\n            leadingIcon={next ? <Plus weight=\"bold\" /> : <Paperclip weight=\"bold\" />}\n            disabled={!next}\n            onClick={() => next && setFiles((current) => [...current, next])}\n          >\n            {next ? \"Attach file\" : \"All files attached\"}\n          </Button>\n        }\n        onSubmit={(value) => setThread((current) => [...current, value])}\n      />\n      <div className=\"flex items-center gap-2 text-xs text-[var(--color-muted)]\">\n        <Badge variant=\"soft\" size=\"sm\">{files.length} attached</Badge>\n        Press Enter to send, Shift and Enter for a new line.\n      </div>\n    </div>\n  )\n}"
}
